#include "sense_notify_private.h"
#include "status.h"
#include "rf.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void sense_notify_doorlock(void)
{
  if(!doorlock_status.bit.lock)
    {
      
          doorlock_status.bit.lock       = 1    ;
          doorlock_status.bit.is_support = TRUE ;
       
      
      rf_icon_set(ICON_LOCK, TRUE);
    
      #if DBG_SENSE == 1
        sense_notify_dbg_print("\nSense Door Lock" , NULL , NULL);      
      #endif    
    }
}
//--------------------------------------------------------------------------//
void sense_notify_doorunlock(void)
{
  if(doorlock_status.bit.lock)
    {
      
          doorlock_status.bit.lock       = 0    ;
          doorlock_status.bit.is_support = TRUE ;
      
    
      rf_icon_clr(ICON_LOCK, TRUE);
    
      #if DBG_SENSE == 1
        sense_notify_dbg_print("\nSense Door Unlock" , NULL , NULL);      
      #endif    
    }
}

